  const error = screen.getByRole('alert');
  expect(error.textContent).toMatch(/Describe the problem/);
  expect(error.textContent).toMatch(/which page/);
  expect(screen.getByLabelText(/What happened/)).toHaveAttribute(
    'aria-describedby',
