					id: entry?.id || "unknown",
					label: entry?.name || entry?.id || "unknown",
					description: entry?.description || "",
					modelSelection: "list",
					modelFlag: null,
					supportsDiagnosis: false,
					isDefault: false,
					models: [],
				};
			}
